import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper structure
    if target_state.empty:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    if cdc_events.empty:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])

    # 1. Remove duplicate events (keep first occurrence of each seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first").reset_index(drop=True)

    # Sort by seq to ensure we process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # 2. Build a dict of target_state for fast lookup
    target_dict = {}
    orders_in_target_state = set()
    if not target_state.empty:
        for _, row in target_state.iterrows():
            order_id = row["order_id"]
            target_dict[order_id] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }
            orders_in_target_state.add(order_id)

    # Track orders that were created or updated (I/U) in this batch
    orders_touched_by_iou = set()

    # Track all applied delete seqs per order (to find minimum)
    applied_delete_seqs = {}

    # 3. Apply events in seq order, per order
    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        order_id = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in target_dict:
            if seq <= target_dict[order_id]["last_seq"]:
                continue

        # Event passes replay guard, so it's applied

        # Apply the operation
        if op in ("I", "U"):
            orders_touched_by_iou.add(order_id)
            if order_id not in target_dict:
                # Create new row
                target_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                # Update existing row
                target_dict[order_id]["status"] = status
                # For 'U' with NULL amount, keep existing amount; otherwise use new amount
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    target_dict[order_id]["amount"] = amount
                target_dict[order_id]["last_seq"] = seq
            # Clear any previous delete seqs when we see an I/U
            if order_id in applied_delete_seqs:
                del applied_delete_seqs[order_id]
        elif op == "D":
            # Track this delete seq
            if order_id not in applied_delete_seqs:
                applied_delete_seqs[order_id] = seq
            else:
                # Keep the minimum seq among all applied deletes
                applied_delete_seqs[order_id] = min(applied_delete_seqs[order_id], seq)
            # Delete the row
            if order_id in target_dict:
                del target_dict[order_id]

    # 4. Build new_state from target_dict
    new_state_rows = []
    for order_id, data in target_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": data["status"],
            "amount": data["amount"],
            "last_seq": data["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "object",
            "amount": "float64",
            "last_seq": "int64"
        })

    # 5. Build tombstones: orders that:
    #    - had a row in target_state OR were created/updated in this batch
    #    - AND have a recorded delete seq (last applied event was 'D')
    tombstone_rows = []

    for order_id, delete_seq in applied_delete_seqs.items():
        # Only tombstone if order had history (was in target_state or was I/U'd)
        if (order_id in orders_in_target_state or order_id in orders_touched_by_iou):
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": delete_seq
            })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
